import {
  HACKER_DESC, MINER_DESC, MAEHWA_DESC,
  ARCHIEVE_DESC, GLITCH_DESC, NOISE_DESC,
  SENTINEL_DESC, LEGACY_DESC, KNIGHT_DESC,
  GUMI_DESC, MUGI_DESC,
} from '../config/abilityParams';

export interface CharacterDef {
  id: string;
  name: string;
  grade: '등급외' | 'R' | 'SR' | 'UR';
  gradeColor: string;   // hex 문자열 (UI용)
  imageKey: string;     // Phaser 텍스처 키 (카드용 스프라이트)
  imagePath: string;    // public/ 기준 경로
  illustKey: string;    // Phaser 텍스처 키 (일러스트 배경용)
  illustPath: string;   // public/ 기준 경로
  videoKey?: string;    // Phaser 비디오 키 (선택, 있으면 일러스트 클릭 시 재생)
  videoPath?: string;   // public/ 기준 경로 (선택)
  basicEffect: string;  // 기본 효과 설명 (상세 팝업용)
  specialAbility: string; // 특수 능력 설명 (없으면 '없음')
  /** 인게임 플레이어 표시 크기 [w, h]. 생략 시 [50, 80] */
  playerDisplaySize?: [number, number];
  /** 캐릭터 선택 카드 표시 크기 [w, h]. 생략 시 [58, 85] */
  cardDisplaySize?: [number, number];
}

/** 등급 이미지 텍스처 키 반환. 등급외 → null */
export function getGradeImgKey(grade: string): string | null {
  if (grade === '등급외') return null;
  return `grade_${grade.toLowerCase()}`; // grade_r, grade_sr, grade_ur
}

export const CHARACTERS: CharacterDef[] = [
  {
    id: 'chibi',
    name: '치비',
    grade: 'R',
    gradeColor: '#44cc88',
    imageKey: 'chibi_front',
    imagePath: 'assets/players/chibi_front.webp',
    illustKey: 'illust_chibi',
    illustPath: 'assets/illustrations/chibi.webp',
    videoKey: 'vid_chibi',
    videoPath: 'assets/vids/chibi.mp4',
    basicEffect: '없음',
    specialAbility: '없음',
  },
  // ── UR등급 ─────────────────────────────────────────────────────────────
  {
    id: 'mugi',
    name: '무기',
    grade: 'UR',
    gradeColor: '#ffaa00',
    imageKey: 'mugi_front',
    imagePath: 'assets/players/mugi_front.webp',
    illustKey: 'illust_mugi',
    illustPath: 'assets/illustrations/mugi.webp',
    videoKey: 'vid_mugi',
    videoPath: 'assets/vids/mugi.mp4',
    basicEffect: MUGI_DESC.basicEffect,
    specialAbility: MUGI_DESC.specialAbility,
    cardDisplaySize: [48, 85],
  },
  {
    id: 'gumi',
    name: '구미',
    grade: 'UR',
    gradeColor: '#ffaa00',
    imageKey: 'gumi_front',
    imagePath: 'assets/players/gumi_front.webp',
    illustKey: 'illust_gumi',
    illustPath: 'assets/illustrations/gumi.webp',
    videoKey: 'vid_gumi',
    videoPath: 'assets/vids/gumi.mp4',
    basicEffect: GUMI_DESC.basicEffect,
    specialAbility: GUMI_DESC.specialAbility,
    playerDisplaySize: [44, 70],
    cardDisplaySize: [51, 74],
  },
  {

/**
 * 캐릭터 능력 수치 설정 (단일 진실 공급원)
 *
 * PARAMS  — 능력 클래스에서 사용하는 숫자/비율 값
 * DESC    — PARAMS로 자동 생성되는 설명 문자열 (character.ts에서 import)
 *
 * 수치를 바꾸면 게임 로직과 캐릭터 정보 패널이 동시에 갱신됩니다.
 */

// ── 루트 (Hacker / SR) ────────────────────────────────────────────────
export const HACKER_PARAMS = {
  deleteInterval: 100,      // 터미널 삭제 점수 간격
  deleteCount: 7,           // 삭제하는 똥 개수
  specialPoopSlowdown: 40,  // 특수 똥 낙하 속도 감소 (px/s)
} as const;

export const HACKER_DESC = {
  basicEffect: '금똥·다이아똥 낙하 속도 감소',
  specialAbility: `${HACKER_PARAMS.deleteInterval}점마다 일반 똥 ${HACKER_PARAMS.deleteCount}개 터미널 삭제`,
} as const;

// ── 광부 (Miner / SR) ─────────────────────────────────────────────────
export const MINER_PARAMS = {
  specialBonus: 5,         // 특수 똥 수집 시 추가 점수
  rainbowInterval: 350,     // 무지개똥 생성 점수 간격
} as const;

export const MINER_DESC = {
  basicEffect: `특수 똥 수집 시 +${MINER_PARAMS.specialBonus}점 추가`,
  specialAbility: `${MINER_PARAMS.rainbowInterval}점마다 무지개똥 생성`,
} as const;

// ── 매화 (Maehwa / SR) ────────────────────────────────────────────────
export const MAEHWA_PARAMS = {
  speedBonus: 50,           // 이동 속도 보너스 (px/s)
  slashInterval: 100,       // 칼 베기 점수 간격
  slashCount: 3,            // 한 번에 베는 똥 개수
  awake2SpecialBonus: 5,    // ★2+ 특수 똥 수집 추가 점수
  synergyBurstInterval: 2000,
  synergyBurstBonus: 150,    // 매화×매화 버스트 발동 시 고정 보너스 점수
} as const;

export const MAEHWA_DESC = {
  basicEffect: `이동 속도 +${MAEHWA_PARAMS.speedBonus}px/s`,
  specialAbility: `${MAEHWA_PARAMS.slashInterval}점마다 위쪽 똥 ${MAEHWA_PARAMS.slashCount}개 칼로 제거`,
} as const;

// ── 아카이브 (Archieve / SR) ──────────────────────────────────────────
export const ARCHIEVE_PARAMS = {
  scoreMultiplierExtra: 0.10, // 점수 배율 추가분 (base의 10% → 1.1배)
  bonusInterval: 200,         // 보너스 점수 간격
  bonusScore: 20,             // 보너스 점수
} as const;

export const ARCHIEVE_DESC = {
  basicEffect: `점수 획득 속도 ${1 + ARCHIEVE_PARAMS.scoreMultiplierExtra}배`,
  specialAbility: `${ARCHIEVE_PARAMS.bonusInterval}점마다 +${ARCHIEVE_PARAMS.bonusScore}점 보너스`,
} as const;

// ── 글리치 (Glitch / SR) ──────────────────────────────────────────────
export const GLITCH_PARAMS = {
  collectInterval: 200,     // 분신 소환 점수 간격
  collectCount: 1,          // 분신이 한 번에 수집하는 특수 똥 개수
} as const;

export const GLITCH_DESC = {
  basicEffect: '잔상 분신이 특수 똥 수집',
  specialAbility: `${GLITCH_PARAMS.collectInterval}점마다 특수 똥 위치에 분신 소환`,
} as const;

// ── 노이즈 (Noise / SR) ───────────────────────────────────────────────
export const NOISE_PARAMS = {
  spawnShortening: 0.25,    // 특수 똥 생성 주기 단축 비율 (25%)
  reductionInterval: 200,   // 소환 감소 점수 간격
  reductionAmount: 2,       // 소환 감소 개수
  goldInterval: 30,         // 금똥 생성 간격 (기본 40의 75%)
  diamondInterval: 75,      // 다이아똥 생성 간격 (기본 100의 75%)
  topazInterval: 135,       // 토파즈똥 생성 간격 (기본 180의 75%)
} as const;

